/* @lc app=leetcode id=1210 lang=kotlin */ class Solution { fun fr(g: Array<IntArray>, r: Int, c: Int) = r in g.indices && c in g.indices && g[r][c] == 0 fun minimumMoves(grid: Array<IntArray>): Int = HashSet<Triple<Int, Int, Int>>().also { it.add(Triple(0, 0, 0)) }.let { seen -> generateSequence(listOf(Triple(0, 0, 0))) { f -> f.flatMap { (r, c, o) -> if (o == 0) listOfNotNull(if (fr(grid, r, c + 2)) Triple(r, c + 1, 0) else null, if (fr(grid, r + 1, c) && fr(grid, r + 1, c + 1)) Triple(r + 1, c, 0) else null, if (fr(grid, r + 1, c) && fr(grid, r + 1, c + 1)) Triple(r, c, 1) else null) else listOfNotNull(if (fr(grid, r + 2, c)) Triple(r + 1, c, 1) else null, if (fr(grid, r, c + 1) && fr(grid, r + 1, c + 1)) Triple(r, c + 1, 1) else null, if (fr(grid, r, c + 1) && fr(grid, r + 1, c + 1)) Triple(r, c, 0) else null) }.filter { seen.add(it) }.takeIf { it.isNotEmpty() } }.indexOfFirst { Triple(grid.size - 1, grid.size - 2, 0) in it } } }